fn empty(n: u8) -> Vec<f64> {
    // Create a vector with the desired size filled with default values (0.0)
    let mut result = Vec::with_capacity(n as usize);
    
    // Fill the vector with 0.0 until it reaches the desired size
    for _ in 0..n {
        result.push(0.0);
    }
    
    result
}

